def profile(c,t):
        z=5*c.pi*t
        # The discarded sinhc tail is <=2 |z|^12/13! for |z|<=10^-6.
        # Even at 30 digits this bound is far below arithmetic roundoff.
        if abs(z)<=c.mpf('1e-6'):
            z2=z*z;s=1+z2/6+z2**2/120+z2**3/5040+z2**4/362880+z2**5/39916800
            return 1/(2*c.pi*s)
        return 5*t/(2*c.sinh(z))

