def exponential_moment(n,start,rate):
    # Exact polynomial prefactor of integral_start^infty x^n exp(-rate*x) dx.
    return sum(sp.Rational(math.factorial(n),math.factorial(j))*start**j/rate**(n-j+1) for j in range(n+1))
